-- 047_callisthenics.sql
-- Three bodyweight (callisthenics) programs, in French, English and German:
-- a beginner and an intermediate plan in eight weeks, and an advanced
-- rotation of four sessions. The app files them, with the bodyweight
-- program, on a callisthenics shelf of their own.
--
-- Deploy: apply this file, in any order with the code. Online, the app
-- shows the catalogue of this table: the programs appear once it is applied.
--
-- Safe to re-run. All-or-nothing: wrapped in one transaction.

BEGIN;

INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
