SELECT 'Advanced callisthenics', 'Four high-volume sessions in rotation: pull, push, legs and a conditioning session. For those who do 10 pull-ups and 15 dips. Once every set is done, slow down the lowering or add a weight.', 'general', 'advanced', 4, true, '[{"name":"Pull","exercises":[{"exerciseName":"Pull-up","targetSets":5,"targetReps":"6-10","restSec":150},{"exerciseName":"Chin-up","targetSets":4,"targetReps":"AMRAP","restSec":120},{"exerciseName":"Hanging Leg Raise","targetSets":4,"targetReps":"10-15","restSec":75},{"exerciseName":"Hollow Hold","targetSets":4,"targetReps":"45-60s","restSec":60}]},{"name":"Push","exercises":[{"exerciseName":"Chest Dip","targetSets":5,"targetReps":"10-15","restSec":120},{"exerciseName":"Handstand Hold","targetSets":5,"targetReps":"30-60s","restSec":90},{"exerciseName":"Push-up","targetSets":4,"targetReps":"20-30","restSec":75},{"exerciseName":"Plank Shoulder Tap","targetSets":3,"targetReps":"30","restSec":45}]},{"name":"Legs","exercises":[{"exerciseName":"Bulgarian Split Squat","targetSets":5,"targetReps":"10-12","restSec":90},{"exerciseName":"Jumping Lunge","targetSets":4,"targetReps":"20","restSec":75},{"exerciseName":"Jump Squat","targetSets":4,"targetReps":"15","restSec":75},{"exerciseName":"Single-Leg Calf Raise","targetSets":4,"targetReps":"15-20","restSec":45},{"exerciseName":"Wall Sit","targetSets":3,"targetReps":"60-90s","restSec":60}]},{"name":"Conditioning","exercises":[{"exerciseName":"Burpee","targetSets":5,"targetReps":"15","restSec":60},{"exerciseName":"Mountain Climber","targetSets":5,"targetReps":"40","restSec":45},{"exerciseName":"Pull-up","targetSets":5,"targetReps":"5","restSec":60},{"exerciseName":"Push-up","targetSets":5,"targetReps":"20","restSec":45},{"exerciseName":"Side Plank","targetSets":3,"targetReps":"45s","restSec":45}]}]'::jsonb, true, 370, 'en'
